-- Каталог рядов WGC Gold ETF Flows (macro_series, source='webbridge') — витрина v_gold_etf_flows.
-- У source='webbridge' нет импортёра, который вызвал бы util.UpsertSeriesCatalog, поэтому
-- описания вносятся сидом (правило 11a AGENTS.md). Применение: make ch-sql FILE=sql/wgc_etf_flows_catalog.sql
-- Идемпотентность: ReplacingMergeTree по (source, series) — повторный прогон перезапишет строки.
-- Значения рядов пишутся НЕ здесь, а через ingest-endpoint POST /v1/manual_series (source='webbridge').
--
-- Набор: 4 метрики × 5 регионов = 20 рядов etf_<метрика>_<регион>. Регионы, метрики и имена
-- заданы в Go (views/gold_etf_flows.go, wgcEtfSeriesNames), тест сверяет с ними этот файл:
-- ряд, забытый в каталоге, для агента не существует — числа он прочитает, семантику нет.
-- Дата точки — последний день отчётного месяца; периодичность — после месячного отчёта WGC
-- (gold.org/goldhub, ~10-е число), ввод одним POST всех 20 рядов.
-- world — мировой итог, остальные четыре региона складываются в него.

INSERT INTO series_catalog (source, series, title, unit, frequency, origin, description) VALUES
